import pandas as pd
import numpy as np


def _num_diff(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def _label_diff(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a.rstrip() != b.rstrip()


def run(inputs: dict) -> dict:
    prev = inputs["snap_prev"].copy()
    curr = inputs["snap_curr"].copy()

    merged = pd.merge(
        prev,
        curr,
        on=["region", "sku"],
        how="outer",
        suffixes=("_prev", "_curr"),
        indicator=True,
    )

    rows = []

    for _, r in merged.iterrows():
        region = r["region"]
        sku = r["sku"]

        if r["_merge"] == "left_only":
            rows.append((region, sku, "D", None))
            continue

        if r["_merge"] == "right_only":
            rows.append((region, sku, "I", None))
            continue

        # both present -> compare
        diffs = []

        if _num_diff(r["price_prev"], r["price_curr"]):
            diffs.append("price")

        if _num_diff(r["stock_prev"], r["stock_curr"]):
            diffs.append("stock")

        if _label_diff(r["label_prev"], r["label_curr"]):
            diffs.append("label")

        if diffs:
            rows.append((region, sku, "U", ",".join(diffs)))
        # no diffs -> no row

    out = pd.DataFrame(rows, columns=["region", "sku", "change_type", "changed_cols"])

    if not out.empty:
        out = out.sort_values(["region", "sku"]).reset_index(drop=True)
    else:
        out = pd.DataFrame(columns=["region", "sku", "change_type", "changed_cols"])

    return {"change_log": out}
